import{_ as a,o as i,c as s,aj as e}from"./chunks/framework.BdtAaXf2.js";const u=JSON.parse('{"title":"你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥！","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥.md","filePath":"AI人工智能/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥.md","lastUpdated":1773722708000,"__rawMarkdown":"# 你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥！\\n\\n> 把看不见的 AI 工作状态，变成一间温馨的像素小屋\\n\\n---\\n\\n## 你有没有想过这个问题？\\n\\n当你说\\"帮我写个方案\\"、\\"查一下资料\\"的时候，AI 助手到底在干嘛？\\n\\n是在疯狂计算？还是偷偷划水？\\n\\n你看不见它的屏幕，听不到它的键盘声，只有一个光标在原地打转……\\n\\n**直到我发现了这个开源项目——Star Office UI。**\\n\\n---\\n\\n## 一间像素风的 AI 办公室\\n\\n这不是什么企业级监控工具，而是一个**超可爱的像素风办公室看板**。\\n\\n你的 AI 助手会变成一个像素小人，在办公室里走来走去：\\n\\n- 写代码时 → 坐在工位上疯狂敲键盘\\n- 搜资料时 → 皱着眉头翻文档\\n- 报错了 → 跑到 Bug 区抓虫子\\n- 没事干 → 瘫在沙发上发呆\\n\\n**6 种状态，3 个区域，实时动画展示。**\\n\\n就像养了一个电子宠物，但这个宠物在帮你干活。\\n\\n---\\n\\n## 更绝的是这些功能\\n\\n### 昨日小记\\n每天自动记录 AI 帮你干了什么，第二天上班打开一看：\\n> \\"昨天帮你写了 3 份文档、修了 2 个 Bug、查了 5 份资料……\\"\\n\\n打工人看了想哭。\\n\\n### 多 Agent 协作\\n你可以邀请其他人的 AI 助手加入你的办公室，大家聚在一起干活。\\n\\n想象一下：你的 AI 在写代码，同事的 AI 在查资料，朋友的 AI 在摸鱼……\\n\\n**一个像素风联合办公空间！**\\n\\n### 中英日三语\\n一键切换语言，你的 AI 办公室瞬间国际化。\\n\\n### AI 生图装修\\n接入 Gemini API，用 AI 给办公室换壁纸。\\n\\n今天赛博朋克风，明天日系治愈系，后天……随你开心。\\n\\n### 手机也能看\\n出门在外，掏出手机瞄一眼，就知道 AI 在干嘛。\\n\\n### 桌面宠物模式\\n甚至可以把它变成透明窗口的桌面宠物，放在屏幕角落陪着你。\\n\\n---\\n\\n## 与 OpenClaw 深度集成\\n\\n如果你是 **OpenClaw（龙虾）** 用户，体验直接拉满。\\n\\n只需跟你的龙虾说一句话：\\n\\n> \\"请按照这个 SKILL.md 帮我完成 Star Office UI 的部署\\"\\n\\n然后？然后就没有然后了。\\n\\n龙虾会自动帮你：\\n- 克隆仓库\\n- 安装依赖\\n- 启动后端\\n- 配置状态同步\\n\\n**最后把访问地址甩给你，打开就能用。**\\n\\n这就是 OpenClaw 的魔力——让 AI 帮你部署一个\\"监控 AI 的办公室\\"。\\n\\n元，太元了。\\n\\n---\\n\\n## 独立部署也很简单\\n\\n\\n\\n不用 OpenClaw 也完全 OK，几行命令就能跑起来：\\n\\n```bash\\n# 克隆项目\\ngit clone https://github.com/ringhyacinth/Star-Office-UI.git\\ncd Star-Office-UI\\n\\n# 安装依赖（需要 Python 3.10+）\\npip install -r backend/requirements.txt\\n\\n# 启动\\ncd backend\\npython app.py\\n```\\n\\n打开 http://127.0.0.1:19000，你的 AI 办公室就开张了。\\n\\n---\\n\\n## 能用来干啥？\\n\\n**个人用户：**\\n- 远程办公时，一眼看到 AI 在干啥\\n- 记录每天的工作内容\\n- 养个桌面宠物，治愈打工的疲惫\\n\\n**团队使用：**\\n- 搭建一个共享的 AI 办公室\\n- 看看团队成员的 AI 都在忙啥\\n- 远程协作更有\\"在办公室\\"的感觉\\n\\n**开发者：**\\n- 作为自己 AI 项目的可视化前端\\n- 学习像素风 UI 设计\\n- 研究 WebSocket 实时通信\\n\\n---\\n\\n## 温馨提示\\n\\n- 代码开源 MIT，随便用\\n- 美术资产禁止商用（仅学习/演示/交流）\\n- 想商用的话，替换成自己的原创素材就行\\n\\n---\\n\\n## 最后\\n\\nStar Office UI 把一个严肃的技术需求——**AI 状态可视化**——做成了一个温暖又可爱的小工具。\\n\\n技术不应该只有冷冰冰的命令行和日志。\\n\\n有时候，它也可以是一间像素风的小办公室，一个会走来走去的电子小人，一份你打开就能看到的\\"昨日小记\\"。\\n\\n**这大概就是开源社区最迷人的地方吧。**\\n\\n---\\n\\n**项目地址：**\\nhttps://github.com/ringhyacinth/Star-Office-UI\\n\\n如果觉得有意思，去给作者点个 Star\\n\\n---\\n\\n*本文由 AI 助手协助创作，部分素材来源于项目 README*\\n\\n---\\n\\n**互动话题：**\\n你最想给你的 AI 助手安排什么工作状态？评论区聊聊"}'),t={name:"AI人工智能/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥/你的 AI 助手在摸鱼？用这个像素风办公室，一眼看穿它在干啥.md"};function l(r,n,p,h,o,c){return i(),s("div",null,[...n[0]||(n[0]=[e("",74)])])}const I=a(t,[["render",l]]);export{u as __pageData,I as default};
